declare(strict_types=1);
namespace Sexogate;
final class Suppliers
{
    public function __construct(private Database $db,private Config $config){}
    private function text(mixed $value,int $min=5,int $max=500):string
    {RuleViolation::ensure(is_string($value)&&mb_strlen(trim($value))>=$min&&mb_strlen($value)<=$max,'INVALID_SUPPLIER_FIELD','Tedarikçi alanlarını ve belge referanslarını kontrol edin.',400);return trim($value);}
    private function quantity(mixed $value):int
    {RuleViolation::ensure(is_int($value)&&$value>=0&&$value<=1000000,'INVALID_QUANTITY','Adet geçersiz.',400);return $value;}
    private function lock(string $supplier):void
    {(new Inventory($this->db,$this->config))->definition('fulfillment-definition',true);RuleViolation::ensure($this->db->one('SELECT id FROM suppliers WHERE id=? AND archived=false FOR UPDATE',[$supplier]),'SUPPLIER_NOT_FOUND','Etkin tedarikçi bulunamadı.',404);}
    private function currency(mixed $v):string
    {RuleViolation::ensure(in_array($v,['TRY','EUR','USD','GBP'],true),'INVALID_CURRENCY','Para birimini kontrol edin.',400);return $v;}
    public function save(array $input,Principal $actor):array
    {
        $actor->require('settings',true);$name=$this->text($input['name']??null,2,300);$days=$this->quantity($input['leadDays']??0);RuleViolation::ensure($days<=365,'INVALID_LEAD_DAYS','Tedarik süresini kontrol edin.',400);$email=$input['email']??'';RuleViolation::ensure(is_string($email)&&($email===''||filter_var($email,FILTER_VALIDATE_EMAIL))&&strlen($email)<=320,'INVALID_EMAIL','E-posta adresini kontrol edin.',400);
        return $this->db->transaction(function()use($input,$actor,$name,$days,$email){$id=$input['id']??Database::id();if(isset($input['id'])){$this->lock($id);$this->db->execute('UPDATE suppliers SET name=?,lead_days=?,contact_email=?,archived=? WHERE id=?',[$name,$days,$email,($input['archived']??false)===true?1:0,$id]);}else $this->db->execute('INSERT INTO suppliers(id,name,lead_days,contact_email) VALUES(?,?,?,?)',[$id,$name,$days,$email]);(new Audit($this->db))->record($actor,'save','suppliers',$id);return ['id'=>$id];});
    }
    public function profile(array $input,Principal $actor):array
    {
        $actor->require('settings',true);$id=$this->text($input['supplierId']??null,1,128);$refs=[];foreach(['contractReference','privacyReference','packagingReference','returnReference'] as $key)$refs[]=$this->text($input[$key]??null);$enabled=($input['enabled']??false)===true;
        return $this->db->transaction(function()use($id,$refs,$enabled,$actor){$this->lock($id);$this->db->execute('INSERT INTO supplier_fulfillment_profiles(supplier_id,enabled,contract_reference,privacy_reference,packaging_reference,return_reference,approved_by) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled),contract_reference=VALUES(contract_reference),privacy_reference=VALUES(privacy_reference),packaging_reference=VALUES(packaging_reference),return_reference=VALUES(return_reference),approved_by=VALUES(approved_by),updated_at=CURRENT_TIMESTAMP(3)',array_merge([$id,(int)$enabled],$refs,[$actor->id]));(new Audit($this->db))->record($actor,'profile','suppliers',$id);return ['id'=>$id,'enabled'=>$enabled];});
    }
    public function route(array $i,Principal $actor):array
    {
        $actor->require('settings',true);$supplier=$this->text($i['supplierId']??null,1,128);$currency=$this->currency($i['currency']??null);$country=$i['country']??'';RuleViolation::ensure(is_string($country)&&preg_match('/\A[A-Z]{2}\z/',$country),'INVALID_COUNTRY','Ülke kodunu kontrol edin.',400);$shipping=Money::amount($i['shippingMinor']??null);$handling=Money::amount($i['handlingMinor']??0);$min=$this->quantity($i['minDays']??null);$max=$this->quantity($i['maxDays']??null);RuleViolation::ensure($max>=$min&&$max<=365,'INVALID_LEAD_DAYS','Hazırlık süresini kontrol edin.',400);$carrier=$this->text($i['carrier']??null,2,191);$ref=$this->text($i['reference']??null);$approved=($i['approved']??false)===true;
        return $this->db->transaction(function()use($supplier,$currency,$country,$shipping,$handling,$min,$max,$carrier,$ref,$approved,$actor){$this->lock($supplier);RuleViolation::ensure($this->db->one('SELECT code FROM country_rules WHERE code=?',[$country]),'COUNTRY_NOT_CONFIGURED','Ülke tanımı gerekir.');$old=$this->db->one('SELECT id FROM supplier_shipping_routes WHERE supplier_id=? AND country=? AND currency=?',[$supplier,$country,$currency]);$id=$old['id']??Database::id();$this->db->execute('INSERT INTO supplier_shipping_routes(id,supplier_id,country,currency,shipping_minor,handling_minor,min_days,max_days,carrier,reference,approved,approved_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE shipping_minor=VALUES(shipping_minor),handling_minor=VALUES(handling_minor),min_days=VALUES(min_days),max_days=VALUES(max_days),carrier=VALUES(carrier),reference=VALUES(reference),approved=VALUES(approved),approved_by=VALUES(approved_by),updated_at=CURRENT_TIMESTAMP(3)',[$id,$supplier,$country,$currency,$shipping,$handling,$min,$max,$carrier,$ref,(int)$approved,$actor->id]);(new Audit($this->db))->record($actor,'route','suppliers',$supplier);return ['id'=>$id];});
    }
    public function offer(array $i,Principal $actor):array
    {
        $actor->require('settings',true);$supplier=$this->text($i['supplierId']??null,1,128);$variant=$this->text($i['variantId']??null,1,128);$sku=$this->text($i['supplierSku']??null,1,191);$currency=$this->currency($i['currency']??null);$cost=Money::amount($i['costMinor']??null);$q=$this->quantity($i['quantity']??null);$safety=$this->quantity($i['safetyStock']??0);$ref=$this->text($i['reference']??null);$approved=($i['approved']??false)===true;
        try{$until=new \DateTimeImmutable($i['validUntil']??'');}catch(\Throwable){throw new RuleViolation('INVALID_VALIDITY','Stok bildiriminin geçerlilik tarihini kontrol edin.',400);}RuleViolation::ensure($until->getTimestamp()>time()&&$until->getTimestamp()<=time()+604800,'INVALID_VALIDITY','Stok bildirimi en fazla yedi gün geçerli olabilir.',400);
        return $this->db->transaction(function()use($supplier,$variant,$sku,$currency,$cost,$q,$safety,$ref,$approved,$until,$actor){$this->lock($supplier);RuleViolation::ensure($this->db->one('SELECT id FROM variants WHERE id=? AND active=true FOR UPDATE',[$variant]),'VARIANT_NOT_FOUND','Etkin seçenek bulunamadı.',404);$old=$this->db->one('SELECT id FROM supplier_offers WHERE supplier_id=? AND variant_id=? AND currency=?',[$supplier,$variant,$currency]);$id=$old['id']??Database::id();$this->db->execute('INSERT INTO supplier_offers(id,supplier_id,variant_id,supplier_sku,currency,cost_minor,reported_quantity,safety_stock,observed_at,valid_until,source_reference,approved,approved_by) VALUES(?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP(3),?,?,?,?) ON DUPLICATE KEY UPDATE supplier_sku=VALUES(supplier_sku),cost_minor=VALUES(cost_minor),reported_quantity=VALUES(reported_quantity),safety_stock=VALUES(safety_stock),observed_at=CURRENT_TIMESTAMP(3),valid_until=VALUES(valid_until),source_reference=VALUES(source_reference),approved=VALUES(approved),approved_by=VALUES(approved_by),updated_at=CURRENT_TIMESTAMP(3)',[$id,$supplier,$variant,$sku,$currency,$cost,$q,$safety,$until->setTimezone(new \DateTimeZone('UTC'))->format('Y-m-d H:i:s.u'),$ref,(int)$approved,$actor->id]);(new Audit($this->db))->record($actor,'stock-report','supplier_offers',$id,['quantity'=>$q]);return ['id'=>$id];});
    }
    public function mode(string $variant,string $mode,Principal $actor):array
    {$actor->require('settings',true);RuleViolation::ensure(in_array($mode,['warehouse','dropship','hybrid'],true),'INVALID_SOURCE','Gönderim kaynağını kontrol edin.',400);return $this->db->transaction(function()use($variant,$mode,$actor){$inventory=new Inventory($this->db,$this->config);$inventory->definition('bundle-definition');$inventory->definition('fulfillment-definition',true);$v=$this->db->one('SELECT lot_tracking FROM variants WHERE id=? FOR UPDATE',[$variant]);RuleViolation::ensure($v,'VARIANT_NOT_FOUND','Seçenek bulunamadı.',404);RuleViolation::ensure($mode==='warehouse'||(!(bool)$v['lot_tracking']&&!$this->db->one('SELECT 1 FROM bundle_components WHERE bundle_variant_id=?',[$variant])),'SUPPLIER_TRACEABILITY_REQUIRED','Set veya lot takipli ürün için dış izlenebilirlik tamamlanmadı.');$this->db->execute('UPDATE variants SET fulfillment_mode=? WHERE id=?',[$mode,$variant]);(new Audit($this->db))->record($actor,'source','variants',$variant,['mode'=>$mode]);return ['id'=>$variant,'mode'=>$mode];});}
    private function group(string $id):array
    {$g=$this->db->one("SELECT order_id FROM order_fulfillment_groups WHERE id=? AND source='supplier'",[$id]);RuleViolation::ensure($g,'GROUP_NOT_FOUND','Tedarikçi paketi bulunamadı.',404);$o=$this->db->one('SELECT id,status,payment_status,address FROM orders WHERE id=? FOR UPDATE',[$g['order_id']]);$g=$this->db->one('SELECT * FROM order_fulfillment_groups WHERE id=? FOR UPDATE',[$id]);RuleViolation::ensure(in_array($o['payment_status'],['succeeded','partially_refunded'],true)&&in_array($o['status'],['confirmed','partially_shipped','shipped'],true),'GROUP_NOT_READY','Ödeme veya sipariş durumu sevke uygun değil.');$g['order']=$o;return $g;}
    public function accept(string $group,string $reference,string $key,Principal $actor):array
    {$actor->require('settings',true);$reference=$this->text($reference);return (new Audit($this->db))->command($actor,$key,['supplier-accept',$group,$reference],function()use($group,$reference,$actor){$g=$this->group($group);RuleViolation::ensure($g['status']==='ready','GROUP_STATE','Bu paketin teyidi zaten kaydedilmiş veya işleme kapalı.');$this->db->execute("UPDATE order_fulfillment_groups SET status='accepted',external_order_reference=?,accepted_at=CURRENT_TIMESTAMP(3),updated_at=CURRENT_TIMESTAMP(3) WHERE id=?",[$reference,$group]);(new Audit($this->db))->record($actor,'accept','supplier_groups',$group);return ['id'=>$group,'status'=>'accepted'];});}
    public function ship(string $group,array $items,string $carrier,string $tracking,string $key,Principal $actor):array
    {
        $actor->require('settings',true);$carrier=$this->text($carrier,2,191);$tracking=$this->text($tracking,5,200);RuleViolation::ensure(count($items)>0&&count($items)<=100,'INVALID_ITEMS','Sevk kalemlerini kontrol edin.',400);usort($items,fn($a,$b)=>strcmp($a['variantId']??'',$b['variantId']??''));
        return (new Audit($this->db))->command($actor,$key,['supplier-ship',$group,$items,$carrier,$tracking],function()use($group,$items,$carrier,$tracking,$actor){$g=$this->group($group);RuleViolation::ensure(in_array($g['status'],['accepted','partially_shipped'],true)&&$g['external_order_reference'],'SUPPLIER_ACK_REQUIRED','Gerçek dış sipariş teyidini kaydedin.');$snapshot=json_decode($g['snapshot'],true,32,JSON_THROW_ON_ERROR);RuleViolation::ensure(($snapshot['carrier']??'')===$carrier,'CARRIER_MISMATCH','Sipariş anında onaylanan taşıyıcı kullanılmalıdır.');$country=json_decode($g['order']['address'],true)['country'];$seen=[];
            foreach($items as $i){$variant=$i['variantId']??'';$q=$this->quantity($i['quantity']??null);$line=$this->db->one('SELECT quantity,snapshot FROM order_items WHERE fulfillment_group_id=? AND variant_id=?',[$group,$variant]);$sent=(int)$this->db->one('SELECT COALESCE(SUM(i.quantity),0) n FROM shipment_items i JOIN shipments s ON s.id=i.shipment_id WHERE s.order_id=? AND i.variant_id=?',[$g['order_id'],$variant])['n'];$held=(int)$this->db->one("SELECT COALESCE(SUM(undispatched_quantity),0) n FROM returns WHERE order_id=? AND variant_id=? AND status NOT IN('requested','rejected')",[$g['order_id'],$variant])['n'];RuleViolation::ensure($line&&$q>0&&!isset($seen[$variant])&&$q+$sent+$held<=(int)$line['quantity'],'SHIPMENT_QUANTITY','Sevk adedi kalan sipariş miktarını aşıyor.');$seen[$variant]=true;
                $v=$this->db->one('SELECT battery_type,liquid FROM variants WHERE id=?',[$variant]);if(!empty($v['battery_type'])||(bool)$v['liquid'])RuleViolation::ensure($this->db->one('SELECT 1 FROM shipping_approvals WHERE variant_id=? AND carrier=LOWER(?) AND country=? AND accepted=true AND(valid_until IS NULL OR valid_until>CURRENT_TIMESTAMP(3))',[$variant,$carrier,$country]),'CARRIER_NOT_APPROVED','Kısıtlı ürün taşıyıcı kabulü gerekir.');
            }
            $id=Database::id();$this->db->execute('INSERT INTO shipments(id,order_id,fulfillment_group_id,carrier,tracking_number) VALUES(?,?,?,?,?)',[$id,$g['order_id'],$group,$carrier,$tracking]);foreach($items as $i)$this->db->execute('INSERT INTO shipment_items(shipment_id,variant_id,quantity) VALUES(?,?,?)',[$id,$i['variantId'],$i['quantity']]);
            $all=$this->db->all('SELECT i.quantity,i.fulfillment_group_id,COALESCE((SELECT SUM(si.quantity) FROM shipment_items si JOIN shipments s ON s.id=si.shipment_id WHERE s.order_id=i.order_id AND si.variant_id=i.variant_id),0) sent FROM order_items i WHERE i.order_id=?',[$g['order_id']]);$complete=true;$groupComplete=true;foreach($all as $line){if((int)$line['sent']<(int)$line['quantity']){$complete=false;if($line['fulfillment_group_id']===$group)$groupComplete=false;}}
            $status=$complete?'shipped':'partially_shipped';$this->db->execute('UPDATE orders SET status=?,fulfillment_status=?,updated_at=CURRENT_TIMESTAMP(3) WHERE id=?',[$status,$status,$g['order_id']]);$this->db->execute('UPDATE order_fulfillment_groups SET status=?,updated_at=CURRENT_TIMESTAMP(3) WHERE id=?',[$groupComplete?'shipped':'partially_shipped',$group]);(new Audit($this->db))->record($actor,'ship','supplier_groups',$group);return ['id'=>$id,'status'=>$status];});
    }
    public function reconcile(string $offer,array $allocations,string $reference,string $key,Principal $actor):array
    {$actor->require('settings',true);$reference=$this->text($reference);RuleViolation::ensure(count($allocations)>0&&count($allocations)<=100&&count(array_unique($allocations))===count($allocations),'INVALID_ALLOCATION','Mutabakat kalemlerini seçin.',400);sort($allocations,SORT_STRING);return (new Audit($this->db))->command($actor,$key,['supplier-reconcile',$offer,$allocations,$reference],function()use($offer,$allocations,$reference,$actor){(new Inventory($this->db,$this->config))->definition('fulfillment-definition',true);RuleViolation::ensure($this->db->one('SELECT id FROM supplier_offers WHERE id=? FOR UPDATE',[$offer]),'OFFER_NOT_FOUND','Stok bildirimi bulunamadı.',404);foreach($allocations as $id){$r=$this->db->one("SELECT r.status,g.external_order_reference,(o.observed_at>g.accepted_at AND o.valid_until>CURRENT_TIMESTAMP(3) AND o.approved=true) fresh_report FROM supplier_reservations r JOIN supplier_offers o ON o.id=r.offer_id JOIN order_items i ON i.order_id=r.order_id AND i.variant_id=r.variant_id JOIN order_fulfillment_groups g ON g.id=i.fulfillment_group_id WHERE r.id=? AND r.offer_id=? FOR UPDATE",[$id,$offer]);RuleViolation::ensure($r&&$r['status']==='allocated'&&$r['external_order_reference']&&(bool)$r['fresh_report'],'ALLOCATION_NOT_RECONCILABLE','Yalnız teyitli ve bu bildirime bağlı tahsis kapatılabilir.');$this->db->execute("UPDATE supplier_reservations SET status='reconciled',reconciliation_reference=? WHERE id=?",[$reference,$id]);}(new Audit($this->db))->record($actor,'reconcile','supplier_offers',$offer,['count'=>count($allocations)]);return ['count'=>count($allocations)];});}
    private function returnEvidence(string $id,string $reference,string $stage,string $key,Principal $actor):array
    {$actor->require('settings',true);$reference=$this->text($reference,5,1000);return (new Audit($this->db))->command($actor,$key,['supplier-return',$id,$reference,$stage],function()use($id,$reference,$stage,$actor){$r=$this->db->one('SELECT order_id FROM returns WHERE id=?',[$id]);RuleViolation::ensure($r,'RETURN_NOT_FOUND','İade bulunamadı.',404);$this->db->one('SELECT id FROM orders WHERE id=? FOR UPDATE',[$r['order_id']]);$r=$this->db->one('SELECT r.status,i.fulfillment_source FROM returns r JOIN order_items i ON i.order_id=r.order_id AND i.variant_id=r.variant_id WHERE r.id=? FOR UPDATE',[$id]);RuleViolation::ensure($r['fulfillment_source']==='supplier'&&$r['status']===($stage==='receipt'?'approved':'received'),'RETURN_STATE','Tedarikçi iadesinin aşamasını kontrol edin.');$this->db->execute('INSERT INTO supplier_return_evidence(return_id,stage,reference,actor_id) VALUES(?,?,?,?)',[$id,$stage,$reference,$actor->id]);$status=$stage==='receipt'?'received':'inspected';if($stage==='receipt')$this->db->execute('UPDATE returns SET status=?,receipt_reference=?,updated_at=CURRENT_TIMESTAMP(3) WHERE id=?',[$status,$reference,$id]);else $this->db->execute("UPDATE returns SET status=?,disposition='quarantine',quality_notes=?,updated_at=CURRENT_TIMESTAMP(3) WHERE id=?",[$status,$reference,$id]);(new Audit($this->db))->record($actor,'supplier-'.$stage,'returns',$id);return ['id'=>$id,'status'=>$status];});}
    public function returnReceived(string $id,string $reference,string $key,Principal $actor):array{return $this->returnEvidence($id,$reference,'receipt',$key,$actor);}
    public function returnInspected(string $id,string $reference,string $key,Principal $actor):array{return $this->returnEvidence($id,$reference,'inspection',$key,$actor);}
    public function listing(Principal $actor):array
    {$actor->require('settings');return ['suppliers'=>$this->db->all('SELECT * FROM suppliers ORDER BY archived,name LIMIT 100'),'profiles'=>$this->db->all('SELECT * FROM supplier_fulfillment_profiles ORDER BY updated_at DESC LIMIT 100'),'routes'=>$this->db->all('SELECT * FROM supplier_shipping_routes ORDER BY updated_at DESC LIMIT 100'),'offers'=>$this->db->all('SELECT o.*,v.sku,s.name supplier FROM supplier_offers o JOIN variants v ON v.id=o.variant_id JOIN suppliers s ON s.id=o.supplier_id ORDER BY o.updated_at DESC LIMIT 100'),'groups'=>$this->db->all("SELECT g.id,g.status,g.external_order_reference,o.number,s.name supplier FROM order_fulfillment_groups g JOIN orders o ON o.id=g.order_id JOIN suppliers s ON s.id=g.supplier_id WHERE g.source='supplier' ORDER BY o.created_at DESC LIMIT 100"),'allocations'=>$this->db->all("SELECT r.id,r.offer_id,r.quantity,r.status,o.number FROM supplier_reservations r JOIN orders o ON o.id=r.order_id WHERE r.status='allocated' ORDER BY r.created_at LIMIT 100")];}
    public function detail(string $id,Principal $actor):array
    {$actor->require('settings');$g=$this->db->one("SELECT g.id,g.order_id,g.status,g.snapshot,g.external_order_reference,o.number,o.address FROM order_fulfillment_groups g JOIN orders o ON o.id=g.order_id WHERE g.id=? AND g.source='supplier' AND o.payment_status IN('succeeded','partially_refunded') AND o.status IN('confirmed','partially_shipped','shipped') AND g.status IN('ready','accepted','partially_shipped','shipped')",[$id]);RuleViolation::ensure($g,'GROUP_NOT_FOUND','Paket bulunamadı.',404);$g['address']=json_decode($g['address'],true);$g['snapshot']=json_decode($g['snapshot'],true);$g['items']=$this->db->all('SELECT i.variant_id,i.sku,i.name,i.quantity,COALESCE((SELECT SUM(si.quantity) FROM shipment_items si JOIN shipments s ON s.id=si.shipment_id WHERE s.fulfillment_group_id=i.fulfillment_group_id AND si.variant_id=i.variant_id),0) sent FROM order_items i WHERE fulfillment_group_id=? ORDER BY i.sku',[$id]);(new Audit($this->db))->record($actor,'view-address','supplier_groups',$id);return $g;}
}
